// This shape allows illegal states: loading=true with data AND error set.
interface RequestState {
  loading?: boolean;
  data?: string[];
  error?: string;
}

function render(state: RequestState): string {
  if (state.loading) return 'spinner';
  if (state.error) return 'error: ' + state.error;
  return 'list of ' + (state.data ? state.data.length : 0);
}

solution.reference:
type RequestState =
  | { status: 'idle' }
  | { status: 'loading' }
  | { status: 'success'; data: string[] }
  | { status: 'error'; message: string };

function assertNever(x: never): never {
  throw new Error('Unhandled variant: ' + JSON.stringify(x));
}

function render(state: RequestState): string {
  switch (state.status) {
    case 'idle':
      return 'idle';
    case 'loading':
      return 'spinner';
    case 'success':
      return 'list of ' + state.data.length;
    case 'error':
      return 'error: ' + state.message;
    default:
      return assertNever(state);
  }
}

