// type Nullable<T> = ...

// 2) UnwrapPromise<T>: Promise<X> -> X, anything else -> itself.
// type UnwrapPromise<T> = ...

interface User {
  id: number;
  name: string;
}

// Should compile:
// type NullableUser = Nullable<User>; // { id: number | null; name: string | null }
// type A = UnwrapPromise<Promise<User>>; // User
// type B = UnwrapPromise<string>; // string

solution.reference:
type Nullable<T> = { [K in keyof T]: T[K] | null };

type UnwrapPromise<T> = T extends Promise<infer U> ? U : T;

interface User {
  id: number;
  name: string;
}

type NullableUser = Nullable<User>; // { id: number | null; name: string | null }
type A = UnwrapPromise<Promise<User>>; // User
type B = UnwrapPromise<string>; // string
// Note: the built-in Awaited<T> additionally unwraps nested Promise<Promise<X>> recursively.

