solution.reference:
import { useState, type MouseEvent } from 'react';

interface CounterProps {
  label: string;
  initial?: number;
  onChange: (next: number) => void;
}

export function Counter({ label, initial = 0, onChange }: CounterProps) {
  const [count, setCount] = useState(initial); // inferred as number

  function handleClick(event: MouseEvent<HTMLButtonElement>) {
    event.preventDefault();
    const next = count + 1;
    setCount(next);
    onChange(next);
  }

  return (
    <button onClick={handleClick}>
      {label}: {count}
    </button>
  );
}

type ApiResult<T, E = ApiError> =
  | { ok: true; data: T }
  | { ok: false; error: E };

Callers cannot touch result.data until they check result.ok — the discriminant narrows the union, so the compiler forces both branches to exist. For richer unions ({ status: 'success' } | { status: 'unauthorized' } | { status: 'rate_limited' }), handlers switch on status and put `const _x: never = result` (or assertNever(result)) in default. When a new variant like { status: 'timeout' } is added, every switch that doesn't handle it fails to compile, turning a silent runtime gap into a build error. Unlike thrown exceptions, the error path is visible in the signature and cannot be forgotten.
